// Self-checking testbench for example_nopk (generated by axilgen.py)
// iverilog -g2012 -o tb example_nopk_tb.v example_nopk.v && vvp tb
`default_nettype none
module tb;
    reg clk = 0, rstn = 0;
    always #5 clk = ~clk;
    reg         awvalid = 0, wvalid = 0, bready = 0, arvalid = 0, rready = 0;
    reg  [31:0] awaddr = 0, araddr = 0, wdata = 0;
    reg  [3:0]  wstrb = 4'hF;
    wire        awready, wready, bvalid, arready, rvalid;
    wire [1:0]  bresp, rresp;
    wire [31:0] rdata;
    wire        o_ctrl_enable;
    wire [2:0]  o_ctrl_mode;
    wire        o_ctrl_start;
    wire        o_ctrl_soft_reset;
    wire [15:0] o_ctrl_divider;
    wire        o_ctrl_wr;
    reg         i_status_busy = 0;
    reg  [7:0]  i_status_level = 0;
    reg  [1:0]  i_status_ext_pin = 0;
    reg         i_irq_done = 0;
    reg         i_irq_error = 0;
    reg  [3:0]  i_irq_overrun = 0;
    reg  [15:0] i_data_rxdata = 0;
    wire [15:0] o_data_txdata;
    wire        o_data_wr;
    wire        o_data_rd;
    wire        o_irq;

    example_nopk #(.C_AXI_ADDR_WIDTH(32)) dut (
        .S_AXI_ACLK(clk), .S_AXI_ARESETN(rstn),
        .S_AXI_AWVALID(awvalid), .S_AXI_AWREADY(awready), .S_AXI_AWADDR(awaddr), .S_AXI_AWPROT(3'd0),
        .S_AXI_WVALID(wvalid), .S_AXI_WREADY(wready), .S_AXI_WDATA(wdata), .S_AXI_WSTRB(wstrb),
        .S_AXI_BVALID(bvalid), .S_AXI_BREADY(bready), .S_AXI_BRESP(bresp),
        .S_AXI_ARVALID(arvalid), .S_AXI_ARREADY(arready), .S_AXI_ARADDR(araddr), .S_AXI_ARPROT(3'd0),
        .S_AXI_RVALID(rvalid), .S_AXI_RREADY(rready), .S_AXI_RDATA(rdata), .S_AXI_RRESP(rresp),
        .o_ctrl_enable(o_ctrl_enable),
        .o_ctrl_mode(o_ctrl_mode),
        .o_ctrl_start(o_ctrl_start),
        .o_ctrl_soft_reset(o_ctrl_soft_reset),
        .o_ctrl_divider(o_ctrl_divider),
        .o_ctrl_wr(o_ctrl_wr),
        .i_status_busy(i_status_busy),
        .i_status_level(i_status_level),
        .i_status_ext_pin(i_status_ext_pin),
        .i_irq_done(i_irq_done),
        .i_irq_error(i_irq_error),
        .i_irq_overrun(i_irq_overrun),
        .i_data_rxdata(i_data_rxdata),
        .o_data_txdata(o_data_txdata),
        .o_data_wr(o_data_wr),
        .o_data_rd(o_data_rd),
        .o_irq(o_irq)
    );

    integer cnt_o_ctrl_start = 0;
    reg  [31:0] last_o_ctrl_start = 0;
    always @(posedge clk) if (|o_ctrl_start) begin cnt_o_ctrl_start = cnt_o_ctrl_start + 1; last_o_ctrl_start = o_ctrl_start; end
    integer cnt_o_ctrl_soft_reset = 0;
    reg  [31:0] last_o_ctrl_soft_reset = 0;
    always @(posedge clk) if (|o_ctrl_soft_reset) begin cnt_o_ctrl_soft_reset = cnt_o_ctrl_soft_reset + 1; last_o_ctrl_soft_reset = o_ctrl_soft_reset; end
    integer cnt_o_ctrl_wr = 0;
    reg  [31:0] last_o_ctrl_wr = 0;
    always @(posedge clk) if (|o_ctrl_wr) begin cnt_o_ctrl_wr = cnt_o_ctrl_wr + 1; last_o_ctrl_wr = o_ctrl_wr; end
    integer cnt_o_data_wr = 0;
    reg  [31:0] last_o_data_wr = 0;
    always @(posedge clk) if (|o_data_wr) begin cnt_o_data_wr = cnt_o_data_wr + 1; last_o_data_wr = o_data_wr; end
    integer cnt_o_data_rd = 0;
    reg  [31:0] last_o_data_rd = 0;
    always @(posedge clk) if (|o_data_rd) begin cnt_o_data_rd = cnt_o_data_rd + 1; last_o_data_rd = o_data_rd; end

    integer errors = 0, checks = 0;
    task check(input [8*48-1:0] name, input [31:0] got, input [31:0] exp);
        begin
            checks = checks + 1;
            if (got !== exp) begin
                errors = errors + 1;
                $display("FAIL %0s: got %h expected %h", name, got, exp);
            end
        end
    endtask
    task axi_write(input [31:0] adr, input [31:0] dat, input [3:0] stb);
        begin
            @(posedge clk); awaddr <= adr; wdata <= dat; wstrb <= stb;
            awvalid <= 1; wvalid <= 1; bready <= 1;
            @(posedge clk); while (!awready) @(posedge clk);
            awvalid <= 0; wvalid <= 0;
            while (!bvalid) @(posedge clk);
            @(posedge clk); bready <= 0;
        end
    endtask
    task axi_read(input [31:0] adr, output [31:0] dat);
        begin
            @(posedge clk); araddr <= adr; arvalid <= 1; rready <= 1;
            @(posedge clk); while (!arready) @(posedge clk);
            arvalid <= 0;
            while (!rvalid) @(posedge clk);
            dat = rdata; @(posedge clk); rready <= 0;
        end
    endtask

    reg [31:0] v;
    initial begin
        repeat (4) @(posedge clk); rstn <= 1; repeat (2) @(posedge clk);

        // 1) Reset values
        axi_read(32'h40002000, v); check("ID reset", v, 32'hA5A50102);
        axi_read(32'h40002004, v); check("CTRL reset", v, 32'h01B20004);
        axi_read(32'h40002008, v); check("STATUS reset", v, 32'h00000000);
        axi_read(32'h4000200C, v); check("IRQ reset", v, 32'h00000000);
        axi_read(32'h40002014, v); check("DATA reset", v, 32'h00000000);

        // ---- ID

        // ---- CTRL
        axi_write(32'h40002004, 32'hD8F10009, 4'hF);
        axi_read(32'h40002004, v); check("CTRL RW write", v, 32'hD8F10009);
        check("o_ctrl_enable", o_ctrl_enable, 32'h1);
        check("o_ctrl_mode", o_ctrl_mode, 32'h4);
        check("o_ctrl_divider", o_ctrl_divider, 32'hD8F1);
        axi_write(32'h40002004, 32'h1027000D, 4'h1);
        axi_read(32'h40002004, v); check("CTRL WSTRB lane 0", v, 32'hD8F1000D);
        cnt_o_ctrl_start = 0;
        axi_write(32'h40002004, 32'hD8F1010D, 4'hF);
        repeat (3) @(posedge clk);
        check("o_ctrl_start one pulse", cnt_o_ctrl_start, 1);
        check("o_ctrl_start value", last_o_ctrl_start, 32'h1);
        check("o_ctrl_start idle", o_ctrl_start, 0);
        cnt_o_ctrl_soft_reset = 0;
        axi_write(32'h40002004, 32'hD8F1020D, 4'hF);
        repeat (3) @(posedge clk);
        check("o_ctrl_soft_reset one pulse", cnt_o_ctrl_soft_reset, 1);
        check("o_ctrl_soft_reset value", last_o_ctrl_soft_reset, 32'h1);
        check("o_ctrl_soft_reset idle", o_ctrl_soft_reset, 0);
        cnt_o_ctrl_wr = 0;
        axi_write(32'h40002004, 32'hD8F1000D, 4'hF);
        repeat (2) @(posedge clk);
        check("o_ctrl_wr strobe", cnt_o_ctrl_wr, 1);

        // ---- STATUS
        i_status_busy = 1'h1;
        i_status_level = 8'h1E;
        i_status_ext_pin = 2'h1;
        repeat (3) @(posedge clk);
        axi_read(32'h40002008, v); check("STATUS RO inputs", v, 32'h000101E1);

        // ---- IRQ
        @(posedge clk) i_irq_done <= 1'h1; @(posedge clk) i_irq_done <= 0;
        axi_read(32'h4000200C, v); check("IRQ.DONE set", v, 32'h00000001);
        check("o_irq set by DONE", o_irq, 1);
        axi_write(32'h4000200C, 32'h00000001, 4'hF);
        axi_read(32'h4000200C, v); check("IRQ.DONE W1C", v, 32'h00000000);
        check("o_irq cleared", o_irq, 0);
        @(posedge clk) i_irq_error <= 1'h1; @(posedge clk) i_irq_error <= 0;
        axi_read(32'h4000200C, v); check("IRQ.ERROR set", v, 32'h00000002);
        check("o_irq set by ERROR", o_irq, 1);
        axi_write(32'h4000200C, 32'h00000002, 4'hF);
        axi_read(32'h4000200C, v); check("IRQ.ERROR W1C", v, 32'h00000000);
        check("o_irq cleared", o_irq, 0);
        @(posedge clk) i_irq_overrun <= 4'hF; @(posedge clk) i_irq_overrun <= 0;
        axi_read(32'h4000200C, v); check("IRQ.OVERRUN set", v, 32'h000000F0);
        axi_write(32'h4000200C, 32'h000000F0, 4'hF);
        axi_read(32'h4000200C, v); check("IRQ.OVERRUN W1C", v, 32'h00000000);

        // ---- DATA
        i_data_rxdata = 16'hC2CE;
        axi_read(32'h40002014, v); check("DATA RO inputs", v, 32'h0000C2CE);
        axi_write(32'h40002014, 32'h73110000, 4'hF);
        axi_read(32'h40002014, v); check("DATA RW write", v, 32'h7311C2CE);
        check("o_data_txdata", o_data_txdata, 32'h7311);
        axi_write(32'h40002014, 32'h78E50000, 4'h1);
        axi_read(32'h40002014, v); check("DATA WSTRB lane 0", v, 32'h7311C2CE);
        cnt_o_data_wr = 0;
        axi_write(32'h40002014, 32'h73110000, 4'hF);
        repeat (2) @(posedge clk);
        check("o_data_wr strobe", cnt_o_data_wr, 1);
        cnt_o_data_rd = 0;
        axi_read(32'h40002014, v);
        repeat (2) @(posedge clk);
        check("o_data_rd strobe", cnt_o_data_rd, 1);

        // Unused offset reads 0
        axi_read(32'h40002010, v); check("unused offset 0x10", v, 0);
        // Final read-back of every register
        axi_read(32'h40002000, v); check("ID final", v, 32'hA5A50102);
        axi_read(32'h40002004, v); check("CTRL final", v, 32'hD8F1000D);
        axi_read(32'h40002008, v); check("STATUS final", v, 32'h000101E1);
        axi_read(32'h4000200C, v); check("IRQ final", v, 32'h00000000);
        axi_read(32'h40002014, v); check("DATA final", v, 32'h7311C2CE);

        $display("%0d checks, %0d errors: %0s", checks, errors, errors ? "FAILED" : "PASSED");
        $finish;
    end
    initial begin #2000000; $display("TIMEOUT"); $finish; end
endmodule
`default_nettype wire
